  .then((r) => console.log(started.join(""), r.join(""), peak));

async function retry(fn, attempts) {
  let lastErr;
  for (let i = 1; i <= attempts; i++) {
    try { return await fn(i); }
    catch (e) { lastErr = e; console.log("attempt", i, "failed"); }
  }
  throw lastErr;
}
